"use client";

import { Fragment, useEffect, useRef, useState, type ReactNode } from "react";
import { PhoneCall, ShieldAlert } from "lucide-react";
import { Button } from "@/components/ui/button";
import { endCall, sendTranscript, startCall, type CallSession } from "@/lib/api";
import demoCall from "@/lib/demo-call.json";
import { cn } from "@/lib/utils";

/**
 * Demo stand-in for a live phone call. The script and its audio (ElevenLabs TTS, generated by
 * `npm run demo-audio`) are fixed; the scoring is not: each line goes to the backend's call
 * endpoint once it has been spoken, as live transcription would, and the backend's scam rules
 * decide the risk and whether to pause payments.
 */
const SCRIPT = demoCall.lines;

/** Pace used when sound is off or a clip can't play. */
const SILENT_LINE_MS = 2600;
const GAP_MS = 350;

/** Words the scorer quoted in its reasons, e.g. `asks for gift cards ("gift cards")`. */
function cues(reasons: string[]): string[] {
  return reasons.flatMap((r) => Array.from(r.matchAll(/"([^"]+)"/g), (m) => m[1]));
}

function highlight(text: string, words: string[]): ReactNode {
  if (words.length === 0) return text;
  const escaped = words.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const parts = text.split(new RegExp(`(${escaped.join("|")})`, "gi"));
  return parts.map((part, i) =>
    words.some((w) => w.toLowerCase() === part.toLowerCase()) ? (
      <mark key={i} className="rounded bg-blocked-soft px-0.5 font-semibold text-blocked">
        {part}
      </mark>
    ) : (
      <Fragment key={i}>{part}</Fragment>
    ),
  );
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function ScamCallDemo() {
  const [call, setCall] = useState<CallSession | null>(null);
  const [lines, setLines] = useState(0);
  const [speaking, setSpeaking] = useState<number | null>(null);
  const [running, setRunning] = useState(false);
  const [sound, setSound] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const cancelled = useRef(false);
  const playing = useRef<HTMLAudioElement | null>(null);
  const audioContext = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
      cancelled.current = true;
      playing.current?.pause();
      void audioContext.current?.close();
    };
  }, []);

  /** Band-limits the clip to roughly 300–3400 Hz so it sounds like a phone line. */
  function phoneLine(audio: HTMLAudioElement) {
    try {
      audioContext.current ??= new AudioContext();
      const ctx = audioContext.current;
      const source = ctx.createMediaElementSource(audio);
      const low = ctx.createBiquadFilter();
      low.type = "highpass";
      low.frequency.value = 300;
      const high = ctx.createBiquadFilter();
      high.type = "lowpass";
      high.frequency.value = 3400;
      source.connect(low).connect(high).connect(ctx.destination);
    } catch {
      // Plain playback is fine.
    }
  }

  async function speak(index: number): Promise<void> {
    if (!sound) return wait(SILENT_LINE_MS);
    const audio = new Audio(`/demo-call/line-${index + 1}.mp3`);
    phoneLine(audio);
    playing.current = audio;
    try {
      await new Promise<void>((resolve, reject) => {
        audio.onended = () => resolve();
        audio.onpause = () => resolve();
        audio.onerror = () => reject(new Error("clip failed"));
        audio.play().catch(reject);
      });
    } catch {
      await wait(SILENT_LINE_MS);
    } finally {
      playing.current = null;
    }
  }

  async function play() {
    cancelled.current = false;
    setRunning(true);
    setError(null);
    setLines(0);
    let session: CallSession | null = null;
    try {
      session = await startCall(demoCall.caller);
      setCall(session);
      await audioContext.current?.resume();
      for (let i = 0; i < SCRIPT.length; i++) {
        await wait(i === 0 ? 500 : GAP_MS);
        if (cancelled.current) break;
        setLines(i + 1);
        setSpeaking(i);
        await speak(i);
        setSpeaking(null);
        if (cancelled.current) break;
        session = await sendTranscript(session.id, SCRIPT[i].text);
        setCall(session);
      }
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "The call could not be replayed.");
    } finally {
      setSpeaking(null);
      if (session) await endCall(session.id).catch(() => undefined);
      setRunning(false);
    }
  }

  function stop() {
    cancelled.current = true;
    playing.current?.pause();
  }

  const risk = Math.round((call?.score.risk ?? 0) * 100);
  const words = cues(call?.score.reasons ?? []);

  return (
    <section className="space-y-3 rounded-md border border-border bg-card px-4 py-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="flex items-center gap-2 text-sm font-semibold">
            <PhoneCall className="h-4 w-4" aria-hidden="true" />
            Call listening
          </h2>
          <p className="text-sm text-muted-foreground">
            Calls from unknown numbers are transcribed and checked line by line.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-1.5 text-sm text-muted-foreground">
            <input
              type="checkbox"
              checked={sound}
              disabled={running}
              onChange={(event) => setSound(event.target.checked)}
            />
            Sound
          </label>
          <Button type="button" size="sm" variant="outline" onClick={running ? stop : () => void play()}>
            {running ? "Hang up" : "Play demo scam call"}
          </Button>
        </div>
      </div>

      {call ? (
        <div className="space-y-3">
          <div className="flex flex-wrap items-center gap-3 text-sm">
            <span className="text-muted-foreground">From {call.caller ?? "an unknown number"}</span>
            <span className="font-semibold">Scam risk {risk}%</span>
            {call.frozeVault ? (
              <span className="inline-flex items-center gap-1 rounded-md bg-blocked-soft px-2 py-1 text-xs font-bold text-blocked">
                <ShieldAlert className="h-4 w-4" aria-hidden="true" />
                Payments paused, family alerted
              </span>
            ) : null}
          </div>
          <div className="h-2 w-full overflow-hidden rounded-full bg-secondary" aria-hidden="true">
            <div
              className={cn("h-full transition-all duration-700", risk >= 60 ? "bg-blocked" : risk > 0 ? "bg-held" : "bg-safe")}
              style={{ width: `${Math.max(risk, 2)}%` }}
            />
          </div>
          <ol className="space-y-1.5 text-sm" aria-live="polite">
            {SCRIPT.slice(0, lines).map((line, i) => (
              <li key={i} className={cn("leading-relaxed", speaking === i && "text-muted-foreground")}>
                <span className="font-semibold">{line.speaker}: </span>
                {highlight(line.text, words)}
                {speaking === i ? <span className="ml-1 animate-pulse">…</span> : null}
              </li>
            ))}
          </ol>
          {call.score.reasons.length > 0 ? (
            <ul className="list-disc space-y-0.5 pl-5 text-sm text-muted-foreground">
              {call.score.reasons.map((reason) => (
                <li key={reason}>{reason}</li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}
      {error ? <p className="text-sm text-blocked">{error}</p> : null}
    </section>
  );
}
